options(survey.lonely.psu='adjust');base<-'.';out<-file.path(base,'NHANES_TB_Stage3_Inference_Audit_20261116');.libPaths(c(file.path(base,'TB_metabolome_exposome_20261115_2130/analysis_MWAS_ExWAS/Rlib'),.libPaths()));library(survey);o<-readRDS(file.path(out,'数据/rebuilt_private.rds'));a<-o$data;cv<-c('age','sex_male','race','educ','PIR','birth','smoking');est<-function(d,f,wt='WTMEC2YR',extra=rep(TRUE,nrow(d))){m<-d$age>=20&complete.cases(model.frame(f,d,na.action=na.pass))&extra;m[is.na(m)]<-FALSE;d$.dom<-m;keep<-is.finite(d[[wt]])&d[[wt]]>0;des<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=as.formula(paste0('~',wt)),nest=TRUE,data=d[keep,]);s<-subset(des,.dom);fit<-svyglm(f,s,family=quasibinomial());b<-coef(fit)['x'];se<-sqrt(vcov(fit)['x','x']);df<-degf(s);data.frame(n=nrow(s$variables),events=sum(s$variables$y),b=b,se=se,OR=exp(b),low=exp(b-qt(.975,df)*se),high=exp(b+qt(.975,df)*se),p=2*pt(-abs(b/se),df),design_df=df,residual_df=fit$df.residual,rank=fit$rank,status=ifelse(fit$converged&&abs(b)<5&&se<2,'ok','unstable'),formula=deparse(f)[1])}
models<-list(M0=y~x+age+sex_male,M1=y~x+age+sex_male+race+birth+smoking,M2=y~x+age+sex_male+race+birth+smoking+educ+PIR,M3=y~x+age+sex_male+race+birth+smoking+educ+PIR+logcot);rr<-lapply(names(models),function(nm)cbind(model=nm,est(a,models[[nm]])));write.csv(do.call(rbind,rr),file.path(out,'数据/06_协变量方案.csv'),row.names=FALSE)
reg<-subset(o$q,layer=='exposome');res<-list();for(i in seq_len(nrow(reg))){q<-reg[i,];v<-q$variable;wt<-q$weight;d<-a;row<-data.frame(variable=v,label=q$label,family=q$class,weight=wt,detected=100-q$pct_below_LOD,n=NA,events=NA,b=NA,se=NA,OR=NA,low=NA,high=NA,p=NA,design_df=NA,residual_df=NA,status='error',message='');tryCatch({if(q$detection_category=='<50% detected'&&!is.na(q$detection_category)){lc<-q$lc_variable;d$x<-ifelse(d[[lc]]%in%c(0,1),as.integer(d[[lc]]==0),NA)}else d$x<-if(q$transform=='log2')ifelse(d[[v]]>0,log2(d[[v]]),NA)else as.numeric(d[[v]]);cov<-cv;if(isTRUE(q$smoking_biomarker))cov<-setdiff(cov,'smoking');if(isTRUE(q$urinary))cov<-c(cov,'logucr');f<-as.formula(paste('y~x+',paste(cov,collapse='+')));f0<-model.frame(f,d,na.action=na.pass);mm<-d$age>=20&complete.cases(f0)&is.finite(d[[wt]])&d[[wt]]>0;mm[is.na(mm)]<-FALSE;if(length(unique(d$x[mm]))<2)stop('no exposure variation');z<-est(d,f,wt);for(k in intersect(names(z),names(row)))row[[k]]<-z[[k]];},error=function(e)row$message<<-conditionMessage(e));res[[i]]<-row};z<-do.call(rbind,res);for(md in c('design','residual','normal')){p<-switch(md,design=z$p,residual=2*pt(-abs(z$b/z$se),z$residual_df),normal=2*pnorm(-abs(z$b/z$se)));p[z$status!='ok'|!is.finite(p)]<-1;z[[paste0('p_',md)]]<-p;z[[paste0('q183_',md)]]<-p.adjust(p,'BH');z[[paste0('q_estimable_',md)]]<-NA;ok<-which(z$status=='ok');z[[paste0('q_estimable_',md)]][ok]<-p.adjust(p[ok],'BH');z[[paste0('q_family_',md)]]<-ave(p,z$family,FUN=function(x)p.adjust(x,'BH'))};write.csv(z,file.path(out,'数据/07_原始XPT_ExWAS.csv'),row.names=FALSE)
# Supplementary selection sensitivity: response probabilities estimated among adult MEC, known basic predictors. Plug-in variance conditions on fitted response weights.
b<-a[a$age>=20&is.finite(a$WTMEC2YR)&a$WTMEC2YR>0&complete.cases(a[,c('age','sex_male','race','birth')]),];b$response<-as.integer(!is.na(b$group));rf<-glm(response~age+sex_male+race+birth,b,family=quasibinomial(),weights=WTMEC2YR/mean(WTMEC2YR));pr<-predict(rf,type='response');b$selection_weight<-b$WTMEC2YR/pmax(pr,.05);rr<-rbind(cbind(model='CC',est(b,models$M2)),cbind(model='IPW_dual_test_plugin',est(b,models$M2,'selection_weight')));write.csv(rr,file.path(out,'数据/08_选择敏感性.csv'),row.names=FALSE);write.csv(data.frame(min_probability=min(pr),max_probability=max(pr),n=nrow(b),target='adult MEC known age sex race birthplace',variance='conditional plugin; response model uncertainty not propagated'),file.path(out,'数据/09_选择模型诊断.csv'),row.names=FALSE)
# Four-category multinomial estimating equations; Taylor sandwich stratified PSU scores.
library(nnet);m<-a$age>=20&!is.na(a$group)&complete.cases(a[,c('x',cv)])&is.finite(a$WTMEC2YR)&a$WTMEC2YR>0;m[is.na(m)]<-FALSE;d<-a[m,];d$g<-factor(d$group,levels=c('Q0T0','Q1T0','Q0T1','Q1T1'));f<-g~x+age+sex_male+race+birth+smoking+educ+PIR;ww<-d$WTMEC2YR/mean(d$WTMEC2YR);fit<-multinom(f,d,weights=ww,trace=FALSE,maxit=1000,Hess=TRUE);X<-model.matrix(f,d);P<-predict(fit,type='probs');K<-3;p<-ncol(X);Y<-sapply(levels(d$g)[-1],function(k)as.numeric(d$g==k));scores<-do.call(cbind,lapply(1:K,function(k)X*as.numeric((Y[,k]-P[,k+1])*ww)));H<-fit$Hessian;hi<-solve(H);allps<-unique(a[is.finite(a$WTMEC2YR)&a$WTMEC2YR>0,c('SDMVSTRA','SDMVPSU')]);U<-matrix(0,nrow(allps),K*p);for(j in 1:nrow(allps))U[j,]<-colSums(scores[d$SDMVSTRA==allps$SDMVSTRA[j]&d$SDMVPSU==allps$SDMVPSU[j],,drop=FALSE]);meat<-matrix(0,K*p,K*p);for(h in unique(allps$SDMVSTRA)){u<-U[allps$SDMVSTRA==h,,drop=FALSE];nh<-nrow(u);if(nh>1){uc<-sweep(u,2,colMeans(u));meat<-meat+crossprod(uc)*nh/(nh-1)}};V<-hi%*%meat%*%hi;bb<-as.vector(t(coef(fit)));idx<-match('x',colnames(X));cons<-list(Q1T0_vs_Q0T1=c(1,-1,0),Q1T0_vs_Q0T0=c(1,0,0),Q0T1_vs_Q0T0=c(0,1,0),Q1T1_vs_Q0T0=c(0,0,1));df<-nrow(allps)-length(unique(allps$SDMVSTRA));mr<-list();for(nm in names(cons)){L<-rep(0,K*p);L[idx+(0:2)*p]<-cons[[nm]];beta<-sum(L*bb);se<-sqrt(drop(t(L)%*%V%*%L));mr[[nm]]<-data.frame(contrast=nm,n=nrow(d),b=beta,se=se,OR=exp(beta),low=exp(beta-qt(.975,df)*se),high=exp(beta+qt(.975,df)*se),p=2*pt(-abs(beta/se),df),design_df=df,n_parameters=K*p,convergence=fit$convergence)};write.csv(do.call(rbind,mr),file.path(out,'数据/10_多项模型.csv'),row.names=FALSE);saveRDS(list(fit=fit,vcov=V,score=scores),file.path(out,'数据/multinomial_private.rds'));cat('DONE\n')
